211	    /**
212	     * The fiscal year a {@code date} belongs to, as a four-digit year. The fiscal year starts on 1 July
213	     * and is identified by the calendar year in which it ends: a date on or after 1 July of year
214	     * {@code Y} belongs to the fiscal year ending in {@code Y + 1}, while a date in January to June of
215	     * year {@code Y} belongs to the fiscal year ending in {@code Y}.
216	     */
217	    public static int fiscalYear(LocalDate date) {
218	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
219	    }
