221	    /**
222	     * The owner's fiscal year, formatted {@code "FY<YY>"} where YY is the last two digits of the
223	     * {@link #fiscalYear(LocalDate) fiscal year} of the business-day-adjusted
224	     * {@link #getRegistrationDate() registrationDate} (e.g. a registration on 2026-10-02 falls in the
225	     * fiscal year ending June 2027, so {@code "FY27"}). {@code null} when no registration date is
226	     * present. Derived per response.
227	     */
228	    public String getFiscalYear() {
229	        if (this.registrationDate == null) {
230	            return null;
