243	    /**
244	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
245	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
246	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
247	     * (so the field is absent from the response) or the registration date is unknown.
248	     */
249	    public String getAgeBand() {
250	        if (this.birthDate == null || this.registrationDate == null) {
251	            return null;
252	        }
253	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
254	        if (age < 18) {
255	            return "MINOR";
256	        }
257	        if (age < 65) {
258	            return "ADULT";
259	        }
260	        return "SENIOR";
261	    }
