394	    /**
395	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
396	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
397	     * {@link #setHouseholdSize(Integer)}); add 3 for a tenure of at least one elapsed fiscal year, i.e.
398	     * the {@code registrationDate} falls in an earlier {@link #fiscalYear(LocalDate) fiscal year} than
399	     * today (fiscal years start 1 July). A newly created owner has zero tenure, so a fresh owner scores
400	     * at most 5 points (2 + 1 + 2).
401	     */
402	    public int getMembershipPoints() {
403	        return membershipPoints(this.householdSize);
404	    }
405	
406	    /** The membership points this owner would score for the given household size; see
407	     * {@link #getMembershipPoints()}. Read-only, so a level can be derived for a hypothetical household
408	     * size without mutating this owner's transient {@link #setHouseholdSize(Integer) householdSize}. */
409	    private int membershipPoints(Integer householdSize) {
410	        int points = 0;
411	        boolean hasEmail = this.email != null && !this.email.isBlank();
412	        if (hasEmail) {
413	            points += 2;
414	        }
415	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
416	        if (unique) {
417	            points += 1;
418	        }
419	        boolean largeHousehold = householdSize != null && householdSize >= 3;
420	        if (largeHousehold) {
421	            points += 2;
422	        }
423	        boolean tenured = this.registrationDate != null
424	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1;
425	        if (tenured) {
426	            points += 3;
427	        }
428	        return points;
429	    }
430	
431	    /**
432	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
433	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. When a
434	     * {@link #getMembershipLevelCap() membershipLevelCap} applies, the derived level is capped to it, so
435	     * a new owner cannot exceed one above the maximum level among their household members.
436	     */
437	    public int getMembershipLevel() {
438	        return membershipLevelForHouseholdSize(this.householdSize);
439	    }
440	
441	    /**
442	     * This owner's membership level as it would be derived for the given household size — i.e. the value
443	     * this owner's own {@code GET} would report when its household holds {@code householdSize} members —
444	     * after applying any {@link #getMembershipLevelCap() cap}. Read-only: used to size a new household
445	     * member's cap from the existing members' levels without mutating their transient household size.
446	     */
447	    public int membershipLevelForHouseholdSize(Integer householdSize) {
448	        int points = membershipPoints(householdSize);
449	        int level;
450	        if (points <= 1) {
451	            level = 1;
452	        }
453	        else if (points <= 3) {
454	            level = 2;
455	        }
456	        else if (points <= 5) {
457	            level = 3;
458	        }
459	        else {
460	            level = 4;
461	        }
462	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
463	            return this.membershipLevelCap;
464	        }
465	        return level;
466	    }
