468	    /**
469	     * Fixed city-to-region table mapping each known city to its canonical region string.
470	     */
471	    private static final Map<String, String> CITY_REGION = Map.of(
472	        "Sydney", "NSW",
473	        "Melbourne", "VIC",
474	        "Brisbane", "QLD");
475	
476	    /**
477	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
478	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
479	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
480	     */
481	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
482	        "NSW", new int[] {2000, 2099},
483	        "VIC", new int[] {3000, 3099},
484	        "QLD", new int[] {4000, 4099});
485	
486	    /**
487	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
488	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
489	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
490	     */
491	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
492	        "NSW", "Australia/Sydney",
493	        "VIC", "Australia/Melbourne",
494	        "QLD", "Australia/Brisbane");
495	
496	    /**
497	     * The canonical region for {@code city} derived from the fixed city-to-region table
498	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
499	     * city is not in the table. The single source of truth for the create-time postcode range check in
500	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
501	     */
502	    public static String regionOf(String city) {
503	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
504	    }
505	
506	    /**
507	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
508	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
509	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
510	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
511	     * postcode range check.
512	     */
513	    public static int[] postcodeRangeOf(String region) {
514	        return REGION_POSTCODES.get(region);
515	    }
516	
517	    /**
518	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
519	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
520	     * range.
521	     */
522	    public static String regionOfPostcode(String postcode) {
523	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
524	            return null;
525	        }
526	        int value = Integer.parseInt(postcode);
527	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
528	            int[] range = entry.getValue();
529	            if (value >= range[0] && value <= range[1]) {
530	                return entry.getKey();
531	            }
532	        }
533	        return null;
534	    }
535	
536	    /**
537	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
538	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
539	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
540	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
541	     * customer code is assigned.
542	     */
543	    public String getLocality() {
544	        if (this.customerCode == null) {
545	            return "UNKNOWN";
546	        }
547	        int dash = this.customerCode.indexOf('-');
548	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
549	    }
550	
551	    /**
552	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
553	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
554	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
555	     * locality maps to no known region.
556	     */
557	    public String getTimezone() {
558	        return REGION_TIMEZONE.get(getLocality());
559	    }
560	
561	    /**
562	     * The single Luhn check digit (0-9) computed over the digits contained in the
563	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
564	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
565	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
566	     */
567	    public int getCheckDigit() {
568	        String code = this.customerCode;
569	        if (code == null) {
570	            return 0;
571	        }
572	        int sum = 0;
573	        boolean dbl = true;
574	        for (int i = code.length() - 1; i >= 0; i--) {
575	            char c = code.charAt(i);
576	            if (c < '0' || c > '9') {
577	                continue;
578	            }
579	            int d = c - '0';
580	            if (dbl) {
581	                d *= 2;
582	                if (d > 9) {
583	                    d -= 9;
584	                }
585	            }
586	            sum += d;
587	            dbl = !dbl;
588	        }
589	        return (10 - (sum % 10)) % 10;
590	    }
