601	    /**
602	     * The single canonical definition of an owner's derived identity key: the lower-case SHA-256 hex
603	     * digest (64 hex characters) of {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}.
604	     * The telephone is used as given (it is expected to already be canonical E.164); the email is
605	     * lower-cased here and a null/blank email or telephone contributes an empty component; the last name is
606	     * reduced to its {@link #soundex(String) Soundex} code so near-spellings share a key component. This is
607	     * the only place the key is composed and hashed; the stored-owner {@link #getIdentityKey()} routes
608	     * through here so the format cannot drift. The key is both a descriptive, returned field and the single
609	     * basis for create-time duplicate detection (two owners with an equal identity key are the same
610	     * identity — a 409; see {@code CheckIdentityUnique}).
611	     */
612	    public static String identityKey(String telephone, String email, String lastName) {
613	        String tel = (telephone == null) ? "" : telephone;
614	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
615	        return Sha256.hex(tel + "|" + mail + "|" + soundex(lastName));
616	    }
617	
618	    /**
619	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and the
620	     * Soundex of its last name via {@link #identityKey(String, String, String)}. Both a descriptive,
621	     * returned value and the single basis for create-time duplicate detection (see
622	     * {@code CheckIdentityUnique}).
623	     */
624	    public String getIdentityKey() {
625	        return identityKey(this.telephone, this.email, this.getLastName());
626	    }
627	
628	    /**
629	     * The American Soundex code of {@code name}: the upper-cased first letter followed by three digits
630	     * derived from the remaining consonants (vowels and the letters H/W are not coded; adjacent letters
631	     * with the same code, and same-coded letters separated only by H/W, collapse to one; a vowel between
632	     * same-coded letters keeps both). Padded with zeros or truncated to exactly four characters. Empty
633	     * when {@code name} holds no letters (or is {@code null}). Used as the last-name component of the
634	     * {@link #identityKey(String, String, String) identity key} so near-spellings share it.
635	     */
636	    public static String soundex(String name) {
637	        if (name == null) {
638	            return "";
639	        }
640	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
641	        if (letters.isEmpty()) {
642	            return "";
643	        }
644	        StringBuilder code = new StringBuilder();
645	        code.append(letters.charAt(0));
646	        char previous = soundexDigit(letters.charAt(0));
647	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
648	            char ch = letters.charAt(i);
649	            if (ch == 'H' || ch == 'W') {
650	                continue; // acts as a separator: keep 'previous' so the flanking letters still collapse
651	            }
652	            char digit = soundexDigit(ch);
653	            if (digit != '0' && digit != previous) {
654	                code.append(digit);
655	            }
656	            previous = digit; // a vowel ('0') resets, so same-coded letters it separates are both coded
657	        }
658	        while (code.length() < 4) {
659	            code.append('0');
660	        }
661	        return code.toString();
662	    }
663	
664	    /** The Soundex digit for a single upper-case letter; {@code '0'} for vowels and H/W (not coded). */
665	    private static char soundexDigit(char ch) {
666	        switch (ch) {
667	            case 'B': case 'F': case 'P': case 'V':
668	                return '1';
669	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
670	                return '2';
671	            case 'D': case 'T':
672	                return '3';
673	            case 'L':
674	                return '4';
675	            case 'M': case 'N':
676	                return '5';
677	            case 'R':
678	                return '6';
679	            default:
680	                return '0';
681	        }
682	    }
683	
684	    protected Set<Pet> getPetsInternal() {
685	        if (this.pets == null) {
686	            this.pets = new HashSet<>();
687	        }
688	        return this.pets;
689	    }
690	
691	    protected void setPetsInternal(Set<Pet> pets) {
692	        this.pets = pets;
693	    }
694	
695	    public List<Pet> getPets() {
696	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
697	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
698	        return Collections.unmodifiableList(sortedPets);
699	    }
700	
701	    public void setPets(List<Pet> pets) {
702	        this.pets = new HashSet<>(pets);
703	    }
704	
705	    public void addPet(Pet pet) {
706	        getPetsInternal().add(pet);
707	        pet.setOwner(this);
708	    }
709	
710	    /**
711	     * Return the Pet with the given name, or null if none found for this Owner.
712	     *
713	     * @param name to test
714	     * @return true if pet name is already in use
715	     */
716	    public Pet getPet(String name) {
717	        return getPet(name, false);
718	    }
719	
720	    /**
721	     * Return the Pet with the given name, or null if none found for this Owner.
722	     *
723	     * @param name to test
724	     * @return true if pet name is already in use
725	     */
726	    public Pet getPet(String name, boolean ignoreNew) {
727	        name = name.toLowerCase();
728	        for (Pet pet : getPetsInternal()) {
729	            if (!ignoreNew || !pet.isNew()) {
730	                String compName = pet.getName();
731	                compName = compName.toLowerCase();
732	                if (compName.equals(name)) {
733	                    return pet;
734	                }
735	            }
736	        }
737	        return null;
738	    }
739	
740	    public Pet getPet(Integer petId) {
741	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
742	    }
743	
744	    @Override
745	    public String toString() {
746	        return new ToStringCreator(this)
747	
748	            .append("id", this.getId())
749	            .append("new", this.isNew())
750	            .append("lastName", this.getLastName())
751	            .append("firstName", this.getFirstName())
752	            .append("address", this.address)
753	            .append("city", this.city)
754	            .append("telephone", this.telephone)
755	            .toString();
756	    }
757	}
